$('#musicPreviewOpen').addEventListener('click',()=>enterMusicFocus(musicSelectedId,$('#musicPreviewOpen')));$('#musicFocusBack').addEventListener('click',()=>exitMusicFocus());$('#musicFocusPlayer').addEventListener('click',()=>{if(musicSelectedId&&ensurePersistentPlayer(musicSelectedId))setDock(true,false)});if(window.LyricsFocus){lyricsFocusController=window.LyricsFocus.createFocusLyricsController({button:$('#musicFocusLyricsToggle'),panel:$('#musicFocusLyrics'),closeButton:$('#musicFocusLyricsClose'),retryButton:$('#musicFocusLyricsRetry'),status:$('#musicFocusLyricsStatus'),credit:$('#musicFocusLyricsCredit'),body:$('#musicFocusLyricsBody'),getTrack:()=>tracks[musicSelectedId]||null,getActiveTrackId:()=>musicSelectedId});}
